import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 998244353;

    static long fastExponentiation(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static long[] precomputedFactorials;

    public static long computeNCr(int n, int r) {
        if (n < r) return 0;
        long numerator = precomputedFactorials[n];
        long denominator = (precomputedFactorials[n - r] * precomputedFactorials[r]) % MOD;
        return (numerator * fastExponentiation(denominator, MOD - 2)) % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int maxN = 200001;
        precomputedFactorials = new long[maxN];
        precomputedFactorials[0] = 1;
        for (int i = 1; i < maxN; i++) {
            precomputedFactorials[i] = (precomputedFactorials[i - 1] * i) % MOD;
        }
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long k = Long.parseLong(input[1]);
        if (k >= n) {
            pw.println(0);
            pw.flush();
            return;
        }
        if (k == 0) {
            pw.println(precomputedFactorials[n]);
            pw.flush();
            return;
        }
        if (k == n - 1) {
            pw.println(2L * n);
            pw.flush();
            return;
        }
        int filledColumns = (int)(n - k);
        long waysToChooseFilledCols = computeNCr(n, filledColumns);
        long totalWays = 0;
        for (int emptyCols = 0; emptyCols <= filledColumns; emptyCols++) {
            long choose = computeNCr(filledColumns, emptyCols);
            long fillWays = fastExponentiation(filledColumns - emptyCols, n);
            long val = (choose * fillWays) % MOD;
            if (emptyCols % 2 == 1) val = (MOD - val) % MOD;
            totalWays = (totalWays + val) % MOD;
        }
        totalWays = (totalWays * waysToChooseFilledCols) % MOD;
        totalWays = (totalWays * 2) % MOD;
        pw.println(totalWays);
        pw.flush();
    }
}
